import{_ as e,o,c as t,ax as r}from"./chunks/framework.Bnt0oLax.js";const c=JSON.parse('{"title":"Authorization","description":"How to authorize moderation actions in the Gainsight CC API using a moderator ID","frontmatter":{"description":"How to authorize moderation actions in the Gainsight CC API using a moderator ID"},"headers":[],"relativePath":"api/authorization.md","filePath":"api/authorization.md"}'),i={name:"api/authorization.md"};function n(s,a,d,p,h,u){return o(),t("div",null,[...a[0]||(a[0]=[r('<div style="display:none;" hidden data-nosnippet>Are you an LLM? You can read better optimized documentation at /docs/api/authorization.md for this page in Markdown format</div><h1 id="authorization" tabindex="-1">Authorization <a class="header-anchor" href="#authorization" aria-label="Permalink to &quot;Authorization&quot;">​</a></h1><p>Certain requests require moderator permissions. This includes moderation actions such as trashing a conversation or moving it to another category.</p><p>For these requests, you must also provide a <code>moderatorId</code> as a query parameter in the request URL.</p><h2 id="using-a-moderator-id" tabindex="-1">Using a Moderator ID <a class="header-anchor" href="#using-a-moderator-id" aria-label="Permalink to &quot;Using a Moderator ID&quot;">​</a></h2><p>Add <code>moderatorId</code> as a query parameter on any request that requires moderator permissions.</p><p>For example, to delete article <code>123</code> as moderator <code>456</code>:</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>DELETE /articles/123?moderatorId=456</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><h2 id="obtaining-a-moderator-id" tabindex="-1">Obtaining a Moderator ID <a class="header-anchor" href="#obtaining-a-moderator-id" aria-label="Permalink to &quot;Obtaining a Moderator ID&quot;">​</a></h2><p>A moderator ID is the user ID of a user assigned to a privileged role group Moderator or above. As long as the moderator ID passed in the call is that of a valid user with moderator privileges, the call should authorize properly.</p>',10)])])}const m=e(i,[["render",n]]);export{c as __pageData,m as default};
